@startuml

class Student {
  + studentId : string
  + dateOfBirth : date
  + city : string
  + region : string
}

class Professor {
  + name : string
  + dateOfBirth : date
  + city : string
}

class Faculty {
  + name : string
  + type : string
}

class Course {
  + code : string
  + lectureHours : int
}

class Exam {
  + grade : string
}

class EnrolledIn {
  + yearOfEnrollment : int
}

Student "1" -- "1" EnrolledIn
EnrolledIn -- "1" Faculty
Student "1" -- "*" Exam
Exam -- "1" Course
Professor "1..*" -- "*" Course : teaches
Faculty "1" -- "1..*" Course : belongs to

@enduml

